// Normaliza el payload de la Cloud API (regla «normalización de entrada» de
// CLAUDE.md) y arrastra lo que puso `Config base`. Nunca se accede a
// `.text.body` fuera de este nodo.
//
// ESTE FLUJO NO DECIDE NADA: manda lo que llegó a `cobroPrepago`, que resuelve
// quién escribe (por el teléfono), qué contestar y qué cobrar, y devuelve todo
// armado. La lógica vive en `admin/functions/src/cobroTextos.ts`, que es puro y
// está probado. Acá solo se extrae y se despacha.
const out = [];
for (const item of $input.all()) {
  const src = item.json;
  const cfg = { ...src };
  for (const k of ['messages', 'contacts', 'statuses', 'errors', 'metadata', 'messaging_product']) {
    delete cfg[k];
  }
  const msg = Array.isArray(src.messages) ? src.messages[0] : undefined;
  if (!msg) continue;

  const tipo = String(msg.type ?? 'desconocido');
  let texto = '';
  let seleccionId = '';
  let mediaId = '';

  switch (tipo) {
    case 'text':
      texto = String(msg.text?.body ?? '');
      break;
    case 'interactive': {
      const sel = msg.interactive?.list_reply ?? msg.interactive?.button_reply;
      seleccionId = String(sel?.id ?? '');
      texto = String(sel?.title ?? '');
      break;
    }
    case 'image':
      mediaId = String(msg.image?.id ?? '');
      texto = String(msg.image?.caption ?? '');
      break;
    case 'document':
      mediaId = String(msg.document?.id ?? '');
      texto = String(msg.document?.caption ?? '');
      break;
    default:
      texto = '';
  }

  const contacto = Array.isArray(src.contacts) ? src.contacts[0] : undefined;
  out.push({ json: Object.assign({}, cfg, {
    from: String(msg.from ?? ''),
    tipo,
    texto,
    seleccionId,
    mediaId,
    mensajeId: String(msg.id ?? ''),
    nombrePerfil: String(contacto?.profile?.name ?? ''),
  }) });
}
return out;

// Traduce la respuesta de `cobroPrepago` en lo que hay que mandar. El
// servidor ya decidió; acá se separa en texto, menú, QR y aviso.
//
// EMPAREJAMIENTO POR ÍNDICE, nunca `.first()`: con dos mensajes simultáneos,
// `.first()` le pondría el teléfono del primero a todos (defecto que ya costó
// una respuesta al teléfono equivocado en el Demo B).
//
// EL CÓDIGO HTTP SE MIRA. Un 200 con `respuesta` es la única respuesta buena.
// Cualquier otra cosa —caída, 401 por credencial, 500— manda el texto de error
// temporal y no inventa ni un menú ni un QR: acá hay dinero, y ante la duda no
// se cobra. `neverError` en el nodo HTTP es lo que permite ver el código; la
// regla real del proyecto no es «nunca neverError», es «nunca ignores el código».
const entradas = $('Normalizar entrada').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const ent = (entradas[i] ?? entradas[entradas.length - 1]).json;
  const r = items[i].json ?? {};
  const codigo = Number(r.statusCode);
  const cuerpo = (r.body && typeof r.body === 'object') ? r.body : {};
  const ok = codigo === 200 && typeof cuerpo.respuesta === 'string' && cuerpo.respuesta.trim() !== '';

  const respuesta = ok ? cuerpo.respuesta : String(ent.mensajeErrorTemporal || 'Tuve un problema para consultar tu cuenta. Intenta de nuevo en un momento.');
  const lista = ok && cuerpo.lista && Array.isArray(cuerpo.lista.secciones) && cuerpo.lista.secciones.length ? cuerpo.lista : null;
  const fichaQr = ok ? String(cuerpo.fichaQr || '') : '';
  const enviarQr = ok && cuerpo.enviarQr === true && /^[0-9a-f]{32}$/.test(fichaQr);

  out.push({ json: {
    respuesta,
    lista,
    enviarLista: Boolean(lista),
    enviarQr,
    qrUrl: enviarQr ? String(ent.urlBaseQr || '') + fichaQr : '',
    epigrafeQr: ok ? String(cuerpo.epigrafeQr || '') : '',
    avisoAdmin: ok ? String(cuerpo.avisoAdmin || '') : '',
    avisoMediaId: ok ? String(cuerpo.avisoMediaId || '') : '',
    tenantId: ok ? String(cuerpo.tenantId || '') : '',
    codigoDelPanel: Number.isFinite(codigo) ? codigo : 0,
    from: ent.from,
    nombrePerfil: ent.nombrePerfil,
    phoneNumberId: ent.phoneNumberId,
    waGraphVersion: ent.waGraphVersion,
    numeroAdminNovuChat: ent.numeroAdminNovuChat,
  } });
}
return out;

