={{ JSON.stringify({
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: $json.from,
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: $json.lista.header },
    body: { text: $json.lista.body },
    footer: { text: $json.lista.footer },
    action: {
      button: $json.lista.boton,
      sections: $json.lista.secciones.map((s) => ({
        title: s.titulo,
        rows: s.filas.map((f) => ({ id: f.id, title: f.titulo, description: f.descripcion })),
      })),
    },
  },
}) }}

